// src/einrichten/anzeige.ts
var ABO_ADRESSE = "https://claude.com/pricing";
function fehlerBild(art) {
  switch (art) {
    case "kein_netz":
      return "netz";
    case "kein_platz":
      return "platz";
    case "frist":
      return "dauer";
    case "signatur":
    case "manifest":
    case "groesse":
    case "pruefsumme":
    case "codesign":
      return "datei";
    default:
      return "allgemein";
  }
}
function prozent(geladen, gesamt) {
  if (!(gesamt > 0))
    return 0;
  return Math.max(0, Math.min(99, Math.floor(geladen / gesamt * 100)));
}
