      u.speicher.wegMelden({ id: `bereit-${a.teil}`, art: "bereit", teil: a.teil, notiz: a.notiz?.trim() || null });
      melden(u, `Bereit zum Ansehen: ${TEIL_NAME[a.teil]}`, TEIL_DATEIEN[a.teil][0] ?? null);
