  "node_modules",
  ".astro",
  ".vite",
  ".next",
  ".nuxt",
  ".svelte-kit",
  ".cache",
  ".turbo",
  ".parcel-cache",
  "dist",
  ".claude",
  ".codex",
  ".gemini",
  ".DS_Store"
